arguments.command:
curl -L -sS -D /tmp/personal-memory.headers -o /tmp/personal-memory.body -w 'exit=%{exitcode}
http_code=%{http_code}
url=%{url_effective}
size_download=%{size_download}
content_type=%{content_type}
redirect_count=%{num_redirects}
' 'http://openblog.com/content/personal-memory-export'; status=$?; printf 'shell_status=%s
' "$status"; printf '%s
' '--- headers ---'; sed -n '1,120p' /tmp/personal-memory.headers; printf '%s
' '--- body bytes ---'; wc -c /tmp/personal-memory.body

